355	func (s *Store) TouchAPIKey(id string, now time.Time) {
356		s.mu.Lock()
357		defer s.mu.Unlock()
358		if k, ok := s.apiKeys[id]; ok {
359			t := now.UTC()
360			k.LastUsedAt = &t
361			s.apiKeys[id] = k
362		}
363	}
