// CouponDuration is how long a coupon discounts a subscription's invoices.
type CouponDuration string

// Coupon durations.
const (
	CouponOnce      CouponDuration = "once"
	CouponRepeating CouponDuration = "repeating"
	CouponForever   CouponDuration = "forever"
)

// Coupon is a discount an organization offers under a code. It is either a percentage of the subtotal or a fixed amount.
type Coupon struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Code  string `json:"code"`
	// PercentOff is 1 to 100; AmountOff is in minor units of Currency. Exactly one of them is set.
	PercentOff int            `json:"percent_off,omitempty"`
	AmountOff  int64          `json:"amount_off,omitempty"`
	Currency   money.Currency `json:"currency,omitempty"`
	Duration   CouponDuration `json:"duration"`
	// DurationInMonths is 1 to 36 for a repeating coupon and 0 otherwise.
	DurationInMonths int `json:"duration_in_months,omitempty"`
	// MaxRedemptions is how many subscriptions may apply the coupon; 0 means no limit.
	MaxRedemptions int `json:"max_redemptions,omitempty"`
	// RedeemBy is the last time the coupon can be applied; nil means no limit.
	RedeemBy      *time.Time `json:"redeem_by,omitempty"`
	TimesRedeemed int        `json:"times_redeemed"`
	CreatedAt     time.Time  `json:"created_at"`
}

