package store

import (
	"regexp"
	"sort"
	"strings"
	"time"
)

// ---- coupons

var couponCodeRe = regexp.MustCompile(`^[A-Za-z0-9_-]{3,32}$`)

// CreateCoupon adds a coupon to an organization. Its code must be unique in the organization, ignoring case.
func (s *Store) CreateCoupon(c Coupon, now time.Time) (Coupon, error) {
	if err := checkCoupon(c); err != nil {
		return Coupon{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[c.OrgID]; !ok {
		return Coupon{}, ErrNotFound
	}
	k := couponKey{c.OrgID, strings.ToLower(c.Code)}
	if _, ok := s.couponIDs[k]; ok {
		return Coupon{}, ErrCodeTaken
	}
	c.ID = s.newID("cpn")
	c.TimesRedeemed = 0
	c.CreatedAt = now.UTC()
	if c.RedeemBy != nil {
		t := c.RedeemBy.UTC()
		c.RedeemBy = &t
	}
	s.coupons[c.ID] = c
	s.couponIDs[k] = c.ID
	return copyCoupon(c), nil
}

// checkCoupon checks a coupon's terms. Zero values mean "not set".
func checkCoupon(c Coupon) error {
	switch {
	case !couponCodeRe.MatchString(c.Code):
		return invalid("a code is 3 to 32 letters, digits, dashes or underscores")
	case (c.PercentOff == 0) == (c.AmountOff == 0):
		return invalid("a coupon takes either percent_off or amount_off")
	case c.PercentOff != 0 && (c.PercentOff < 1 || c.PercentOff > 100):
		return invalid("percent_off is 1 to 100")
	case c.AmountOff < 0:
		return invalid("amount_off is positive")
	case c.AmountOff != 0 && !c.Currency.Valid():
		return invalid("unknown currency %q", c.Currency)
	case c.Duration != CouponOnce && c.Duration != CouponRepeating && c.Duration != CouponForever:
		return invalid("a coupon's duration is once, repeating or forever")
	case c.Duration == CouponRepeating && (c.DurationInMonths < 1 || c.DurationInMonths > 36):
		return invalid("duration_in_months is 1 to 36 for a repeating coupon")
	case c.Duration != CouponRepeating && c.DurationInMonths != 0:
		return invalid("duration_in_months is only for a repeating coupon")
	case c.MaxRedemptions < 0:
		return invalid("max_redemptions is at least 1")
	}
	return nil
}

// Coupon returns one of an organization's coupons by its code, ignoring case.
func (s *Store) Coupon(orgID, code string) (Coupon, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.couponIDs[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return Coupon{}, false
	}
	return copyCoupon(s.coupons[id]), true
}

// Coupons returns an organization's coupons, oldest first.
func (s *Store) Coupons(orgID string) []Coupon {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, copyCoupon(c))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// RedeemCoupon applies the organization's coupon with this code to one of its subscriptions at now. A subscription has at
// most one coupon, and a coupon is refused once its redeem-by time has passed, once max_redemptions subscriptions have it,
// and when its currency is not the plan's (for an amount off).
func (s *Store) RedeemCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	id, ok := s.couponIDs[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return Subscription{}, ErrNotFound
	}
	c := s.coupons[id]
	switch {
	case sub.Status == Canceled:
		return Subscription{}, ErrCanceled
	case sub.Coupon != "":
		return Subscription{}, ErrCouponApplied
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && c.TimesRedeemed >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.AmountOff != 0 && c.Currency != s.plans[sub.PlanID].Currency:
		return Subscription{}, ErrCurrencyMismatch
	}
	c.TimesRedeemed++
	s.coupons[id] = c
	t := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &t
	s.subs[subID] = sub
	return copySub(sub), nil
}

func copyCoupon(c Coupon) Coupon {
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
	return c
}

