package api

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// couponInput is a coupon as a request sends it. Optional numbers are pointers, so an explicit zero can be refused.
type couponInput struct {
	Code             string               `json:"code"`
	PercentOff       *int                 `json:"percent_off"`
	AmountOff        *string              `json:"amount_off"` // major units, such as "5.00"
	Currency         money.Currency       `json:"currency"`
	Duration         store.CouponDuration `json:"duration"`
	DurationInMonths *int                 `json:"duration_in_months"`
	MaxRedemptions   *int                 `json:"max_redemptions"`
	RedeemBy         *string              `json:"redeem_by"` // RFC 3339
}

// coupon checks the input's shape and returns the coupon it describes. The store checks the rest.
func (in couponInput) coupon(orgID string) (store.Coupon, error) {
	c := store.Coupon{OrgID: orgID, Code: in.Code, Currency: in.Currency, Duration: in.Duration}
	bad := func(msg string) error { return fmt.Errorf("%w: %s", store.ErrInvalid, msg) }
	if (in.PercentOff == nil) == (in.AmountOff == nil) {
		return store.Coupon{}, bad("a coupon takes either percent_off or amount_off")
	}
	if in.PercentOff != nil {
		if *in.PercentOff < 1 {
			return store.Coupon{}, bad("percent_off is 1 to 100")
		}
		c.PercentOff = *in.PercentOff
	}
	if in.AmountOff != nil {
		n, err := money.ParseMajor(*in.AmountOff, in.Currency)
		if err != nil || n <= 0 {
			return store.Coupon{}, bad("amount_off is a positive amount in major units, such as \"5.00\"")
		}
		c.AmountOff = n
	}
	if in.DurationInMonths != nil {
		if in.Duration != store.CouponRepeating {
			return store.Coupon{}, bad("duration_in_months is only for a repeating coupon")
		}
		c.DurationInMonths = *in.DurationInMonths
	}
	if in.MaxRedemptions != nil {
		if *in.MaxRedemptions < 1 {
			return store.Coupon{}, bad("max_redemptions is at least 1")
		}
		c.MaxRedemptions = *in.MaxRedemptions
	}
	if in.RedeemBy != nil {
		t, err := time.Parse(time.RFC3339, *in.RedeemBy)
		if err != nil {
			return store.Coupon{}, bad("redeem_by is an RFC 3339 time")
		}
		c.RedeemBy = &t
	}
	return c, nil
}

// decodeTyped reads a JSON body like decode, but answers a field of the wrong type with 422 invalid, as the body is
// well-formed JSON that describes something invalid.
func decodeTyped(w http.ResponseWriter, r *http.Request, v any) bool {
	err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(v)
	var typeErr *json.UnmarshalTypeError
	switch {
	case errors.As(err, &typeErr):
		writeError(w, http.StatusUnprocessableEntity, "invalid", fmt.Sprintf("%s must be %s", typeErr.Field, typeErr.Type))
		return false
	case err != nil:
		writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
		return false
	}
	return true
}

func couponKeyOf(c store.Coupon) cursor { return cursor{T: c.CreatedAt, ID: c.ID} }

// listCoupons lists the organization's coupons, oldest first.
func (s *Server) listCoupons(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	items, next := pageOf(s.store.Coupons(p.OrgID), couponKeyOf, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in couponInput
	if !decodeTyped(w, r, &in) {
		return
	}
	c, err := in.coupon(p.OrgID)
	if err != nil {
		s.storeError(w, err)
		return
	}
	c, err = s.store.CreateCoupon(c, s.clock.Now())
	if errors.Is(err, store.ErrCodeTaken) {
		writeError(w, http.StatusConflict, "code_taken", err.Error())
		return
	}
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, c)
}

func (s *Server) getCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	c, ok := s.store.Coupon(p.OrgID, r.PathValue("code"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such coupon")
		return
	}
	writeJSON(w, http.StatusOK, c)
}

// applyCoupon applies a coupon to a subscription: {"code": "..."}.
func (s *Server) applyCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Code string `json:"code"`
	}
	if !decodeTyped(w, r, &in) {
		return
	}
	sub, err := s.subs.RedeemCoupon(r.Context(), p.OrgID, r.PathValue("id"), in.Code)
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

