package api_test

import (
	"net/http"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

func TestCreateCoupon(t *testing.T) {
	e := apitest.New(t)
	var c store.Coupon
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "Spring-25", "amount_off": "25.50", "currency": "USD", "duration": "once"}, &c)
	if c.Code != "Spring-25" || c.AmountOff != 2550 || c.Currency != "USD" || c.Duration != store.CouponOnce || c.PercentOff != 0 || c.TimesRedeemed != 0 {
		t.Fatalf("coupon = %+v", c)
	}
	if r := e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "HALF", "percent_off": 50, "duration": "repeating", "duration_in_months": 3, "max_redemptions": 5, "redeem_by": "2027-01-01T00:00:00Z"}, nil); true {
		m := r.Map(t)
		if m["times_redeemed"] != float64(0) || m["duration_in_months"] != float64(3) || m["max_redemptions"] != float64(5) || m["redeem_by"] != "2027-01-01T00:00:00Z" || m["amount_off"] != nil {
			t.Fatalf("percent coupon = %v", m)
		}
	}
	// Codes are unique in the organization, ignoring case; another organization may use the same code.
	if r := e.Do("POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "spring-25", "percent_off": 10, "duration": "forever"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "code_taken" {
		t.Fatalf("duplicate code: %s", r)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Globex.Key, map[string]any{"code": "SPRING-25", "percent_off": 10, "duration": "forever"}, nil)
}

func TestCreateCouponRefusesInvalidTerms(t *testing.T) {
	e := apitest.New(t)
	bodies := []string{
		`{"code":"ab","percent_off":10,"duration":"once"}`,
		`{"code":"has space","percent_off":10,"duration":"once"}`,
		`{"code":"` + strings.Repeat("a", 33) + `","percent_off":10,"duration":"once"}`,
		`{"code":"BOTH","percent_off":10,"amount_off":"5.00","currency":"USD","duration":"once"}`,
		`{"code":"NEITHER","duration":"once"}`,
		`{"code":"ZERO","percent_off":0,"duration":"once"}`,
		`{"code":"BIG","percent_off":101,"duration":"once"}`,
		`{"code":"TEXT","percent_off":"10","duration":"once"}`,
		`{"code":"AMT","amount_off":"abc","currency":"USD","duration":"once"}`,
		`{"code":"FREE","amount_off":"0","currency":"USD","duration":"once"}`,
		`{"code":"CUR","amount_off":"5.00","currency":"XXX","duration":"once"}`,
		`{"code":"NUM","amount_off":5,"currency":"USD","duration":"once"}`,
		`{"code":"SOON","percent_off":10,"duration":"sometimes"}`,
		`{"code":"REP","percent_off":10,"duration":"repeating"}`,
		`{"code":"MON","percent_off":10,"duration":"once","duration_in_months":3}`,
		`{"code":"LONG","percent_off":10,"duration":"repeating","duration_in_months":37}`,
		`{"code":"ZMO","percent_off":10,"duration":"repeating","duration_in_months":0}`,
		`{"code":"MAX","percent_off":10,"duration":"forever","max_redemptions":0}`,
		`{"code":"LATE","percent_off":10,"duration":"forever","redeem_by":"tomorrow"}`,
	}
	for _, b := range bodies {
		if r := e.Do("POST", "/v1/coupons", e.Acme.Key, b); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid" {
			t.Errorf("%s: %s", b, r)
		}
	}
	if got := e.Store.Coupons(e.Acme.ID); len(got) != 0 {
		t.Fatalf("refused coupons were stored: %+v", got)
	}
}

func TestGetAndListCoupons(t *testing.T) {
	e := apitest.New(t)
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "FIRST", "percent_off": 10, "duration": "forever"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "SECOND", "percent_off": 20, "duration": "forever"}, nil)

	var c store.Coupon
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/second", e.Acme.Key, nil, &c)
	if c.Code != "SECOND" || c.PercentOff != 20 {
		t.Fatalf("get = %+v", c)
	}
	if r := e.Do("GET", "/v1/coupons/SECOND", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("another organization's coupon: %s", r)
	}
	var list struct{ Items []store.Coupon }
	e.MustDo(http.StatusOK, "GET", "/v1/coupons", e.Acme.Key, nil, &list)
	if len(list.Items) != 2 || list.Items[0].Code != "FIRST" || list.Items[1].Code != "SECOND" {
		t.Fatalf("list = %+v", list.Items)
	}
}

func TestApplyCoupon(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	subscribe := func() store.Subscription {
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID}, &sub)
