func TestApplyCoupon(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	subscribe := func() store.Subscription {
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID}, &sub)
		return sub
	}
	apply := func(sub store.Subscription, code string) *apitest.Response {
		return e.Do("POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]string{"code": code})
	}
	coupon := func(body map[string]any) {
		e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, body, nil)
	}
	coupon(map[string]any{"code": "HALF", "percent_off": 50, "duration": "forever"})
	coupon(map[string]any{"code": "ONE", "percent_off": 10, "duration": "forever", "max_redemptions": 1})
	coupon(map[string]any{"code": "EUROFIVE", "amount_off": "5.00", "currency": "EUR", "duration": "once"})
	coupon(map[string]any{"code": "OLD", "percent_off": 10, "duration": "once", "redeem_by": "2026-02-01T00:00:00Z"})

	sub, second, third := subscribe(), subscribe(), subscribe()

	if r := apply(sub, "NOPE"); r.Code != http.StatusNotFound {
		t.Fatalf("unknown code: %s", r)
	}
	if r := apply(sub, "EUROFIVE"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "currency_mismatch" {
		t.Fatalf("currency: %s", r)
	}
	var applied store.Subscription
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]string{"code": "half"}, &applied)
	if applied.Coupon != "HALF" || applied.CouponRedeemedAt == nil || !applied.CouponRedeemedAt.Equal(e.Clock.Now()) {
		t.Fatalf("subscription = %+v", applied)
	}
	if r := apply(sub, "ONE"); r.Code != http.StatusConflict || r.Map(t)["error"] != "coupon_already_applied" {
		t.Fatalf("second coupon: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+second.ID+"/coupon", e.Acme.Key, map[string]string{"code": "ONE"}, nil)
	if r := apply(third, "ONE"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_exhausted" {
		t.Fatalf("exhausted: %s", r)
	}
	e.Clock.Set(e.Clock.Now().AddDate(0, 1, 0))
	if r := apply(third, "OLD"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_expired" {
		t.Fatalf("expired: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+third.ID+"/cancel", e.Acme.Key, nil, nil)
	if r := apply(third, "HALF"); r.Code != http.StatusConflict || r.Map(t)["error"] != "subscription_canceled" {
		t.Fatalf("canceled: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions/sub_999999/coupon", e.Acme.Key, map[string]string{"code": "HALF"}); r.Code != http.StatusNotFound {
		t.Fatalf("unknown subscription: %s", r)
	}

	var one store.Coupon
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/ONE", e.Acme.Key, nil, &one)
	if one.TimesRedeemed != 1 {
		t.Fatalf("ONE redeemed %d times, want 1", one.TimesRedeemed)
	}
}

