func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}}
	cases := []struct {
		name string
		inv  store.Invoice
		want Totals
	}{
		// The coupon replaces DiscountPercent. 15% of 5499 = 824.85 -> 825; taxable 4674; tax 385.605 -> 386.
		{"percent", store.Invoice{Lines: lines, DiscountPercent: 10, TaxRateBP: 825, Coupon: "SPRING", CouponPercentOff: 15},
			Totals{Subtotal: 5499, Discount: 825, Tax: 386, Total: 5060}},
		// Taxable 4499; tax 371.1675 -> 371.
		{"amount", store.Invoice{Lines: lines, TaxRateBP: 825, Coupon: "FIVE", CouponAmountOff: 1000},
			Totals{Subtotal: 5499, Discount: 1000, Tax: 371, Total: 4870}},
		{"amount capped at the subtotal", store.Invoice{Lines: lines, Coupon: "BIG", CouponAmountOff: 9000},
			Totals{Subtotal: 5499, Discount: 5499}},
	}
	for _, tc := range cases {
		if got := Compute(tc.inv); got != tc.want {
			t.Errorf("%s: Compute = %+v, want %+v", tc.name, got, tc.want)
		}
	}
}

