	"time"
)

func TestCouponCodesAreUniquePerOrganization(t *testing.T) {
	s := New()
	acme, globex := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	now := time.Date(2026, 1, 15, 10, 0, 0, 0, time.UTC)
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "Spring", PercentOff: 10, Duration: CouponOnce}, now); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "SPRING", PercentOff: 20, Duration: CouponOnce}, now); !errors.Is(err, ErrCodeTaken) {
		t.Fatalf("duplicate code: %v", err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: globex.ID, Code: "spring", PercentOff: 20, Duration: CouponOnce}, now); err != nil {
		t.Fatalf("another organization's code: %v", err)
	}
	if c, ok := s.Coupon(acme.ID, "spring"); !ok || c.Code != "Spring" {
		t.Fatalf("Coupon = %+v, %v", c, ok)
	}
}

func TestCheckCouponRefusesBadTerms(t *testing.T) {
	bad := []Coupon{
		{Code: "ab", PercentOff: 10, Duration: CouponOnce},
		{Code: "BOTH", PercentOff: 10, AmountOff: 500, Currency: "USD", Duration: CouponOnce},
		{Code: "NEITHER", Duration: CouponOnce},
		{Code: "NOCUR", AmountOff: 500, Duration: CouponOnce},
		{Code: "REPEAT", PercentOff: 10, Duration: CouponRepeating},
		{Code: "ONCEMONTHS", PercentOff: 10, Duration: CouponOnce, DurationInMonths: 2},
		{Code: "CAP", PercentOff: 101, Duration: CouponForever},
		{Code: "MAXNEG", PercentOff: 10, Duration: CouponForever, MaxRedemptions: -1},
	}
	for _, c := range bad {
		if err := checkCoupon(c); !errors.Is(err, ErrInvalid) {
			t.Errorf("%+v: %v", c, err)
		}
	}
}

func TestCouponsSurviveExport(t *testing.T) {
	s := New()
	acme := newOrg(t, s, "Acme")
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "KEEP", PercentOff: 10, Duration: CouponForever}, time.Now()); err != nil {
		t.Fatal(err)
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if c, ok := s2.Coupon(acme.ID, "keep"); !ok || c.PercentOff != 10 {
		t.Fatalf("restored coupon = %+v, %v", c, ok)
	}
	if _, err := s2.CreateCoupon(Coupon{OrgID: acme.ID, Code: "Keep", PercentOff: 5, Duration: CouponForever}, time.Now()); !errors.Is(err, ErrCodeTaken) {
		t.Fatalf("restored code is not reserved: %v", err)
	}
}

