// couponFor returns the coupon that discounts an invoice created at now for the period starting at start, if one does. A
// coupon discounts the invoices created after it was applied: once, only the first of them; repeating, those whose period
// starts less than its duration in months after the redemption; forever, all of them.
func (s *Service) couponFor(sub store.Subscription, start, now time.Time) (store.Coupon, bool) {
	if sub.Coupon == "" || sub.CouponRedeemedAt == nil || now.Before(*sub.CouponRedeemedAt) {
		return store.Coupon{}, false
	}
	c, ok := s.Store.Coupon(sub.OrgID, sub.Coupon)
	if !ok {
		return store.Coupon{}, false
	}
	switch c.Duration {
	case store.CouponOnce:
		for _, inv := range s.Store.ListInvoices(sub.OrgID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
			if inv.Coupon == c.Code {
				return store.Coupon{}, false
			}
		}
	case store.CouponRepeating:
		if !start.Before(sub.CouponRedeemedAt.AddDate(0, c.DurationInMonths, 0)) {
			return store.Coupon{}, false
		}
	}
	return c, true
}

