package subscriptions_test

import (
	"context"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// A 10% coupon applied on January 20 to a subscription with a 50% discount_percent. Each case says which of the four
// monthly invoices (January to April) the coupon discounts; the others take the subscription's discount_percent.
func TestCouponDiscountsInvoicesByDuration(t *testing.T) {
	cases := []struct {
		name     string
		duration store.CouponDuration
		months   int
		coupon   []bool
	}{
		{"once", store.CouponOnce, 0, []bool{false, true, false, false}},
		{"repeating for two months", store.CouponRepeating, 2, []bool{false, true, true, false}},
		{"forever", store.CouponForever, 0, []bool{false, true, true, true}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			e := apitest.New(t)
			ctx := context.Background()
			c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
			p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
			sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1, DiscountPercent: 50})
			if err != nil {
				t.Fatal(err)
			}
			e.Clock.Set(apitest.Start.AddDate(0, 0, 5))
			coupon := store.Coupon{OrgID: e.Acme.ID, Code: "TENOFF", PercentOff: 10, Duration: tc.duration, DurationInMonths: tc.months}
			if _, err := e.Store.CreateCoupon(coupon, e.Clock.Now()); err != nil {
				t.Fatal(err)
			}
			if _, err := e.Subs.RedeemCoupon(ctx, e.Acme.ID, sub.ID, "tenoff"); err != nil {
				t.Fatal(err)
			}
			if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.Coupon != "TENOFF" || got.CouponRedeemedAt == nil {
				t.Fatalf("subscription = %+v", got)
			}
			for range len(tc.coupon) - 1 {
				cur, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
				e.Clock.Set(cur.CurrentPeriodEnd)
				if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
					t.Fatalf("RenewDue = %d, %v", n, err)
				}
			}
			invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
			if len(invs) != len(tc.coupon) {
				t.Fatalf("got %d invoices, want %d", len(invs), len(tc.coupon))
			}
			for i, inv := range invs {
				want := int64(1000) // 50% of 2000 from the subscription's discount_percent
				if tc.coupon[i] {
					want = 200 // 10% of 2000 from the coupon
				}
				if got := billing.Compute(inv).Discount; got != want || (inv.Coupon != "") != tc.coupon[i] {
					t.Fatalf("invoice %d: discount %d, coupon %q; want discount %d, coupon applied %v", i, got, inv.Coupon, want, tc.coupon[i])
				}
			}
		})
	}
}

// An amount off is taken from the subtotal but never more than the subtotal, and the tax is charged on what is left.
func TestAmountOffCouponIsCappedAtTheSubtotal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Store.CreateCoupon(store.Coupon{OrgID: e.Acme.ID, Code: "BIGOFF", AmountOff: 5000, Currency: "USD", Duration: store.CouponForever}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.RedeemCoupon(ctx, e.Acme.ID, sub.ID, "BIGOFF"); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 {
		t.Fatalf("got %d invoices, want 2", len(invs))
	}
	if got := billing.Compute(invs[1]); got != (billing.Totals{Subtotal: 2000, Discount: 2000, Total: 0}) {
		t.Fatalf("capped invoice = %+v", got)
	}
}
