// An amount off in one currency does not discount an invoice in another. After the plan changes to EUR, the USD coupon
// stays on the subscription but the next invoice is charged in full.
func TestAmountOffCouponSkipsInvoicesInAnotherCurrency(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	usd := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	eur := e.CreatePlan(e.Acme, "Team EUR", "EUR", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: usd.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Store.CreateCoupon(store.Coupon{OrgID: e.Acme.ID, Code: "FIVEOFF", AmountOff: 500, Currency: "USD", Duration: store.CouponForever}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.RedeemCoupon(ctx, e.Acme.ID, sub.ID, "FIVEOFF"); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &eur.ID}); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 {
		t.Fatalf("got %d invoices, want 2", len(invs))
	}
	if got := invs[1]; got.Currency != money.Currency("EUR") || got.Coupon != "" || billing.Compute(got).Discount != 0 {
		t.Fatalf("EUR invoice = %+v, discount %d; want no coupon and no discount", got, billing.Compute(got).Discount)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.Coupon != "FIVEOFF" {
		t.Fatalf("subscription coupon = %q, want FIVEOFF kept", got.Coupon)
	}
}
EOF
